// InternalKey ordering: userKey ASC, seqNum DESC (newest version wins)
record InternalKey(byte[] userKey, long seqNum, byte opType) implements Comparable<InternalKey> {
    @Override
    public int compareTo(InternalKey o) {
        int cmp = Arrays.compareUnsigned(this.userKey, o.userKey);
        if (cmp != 0) return cmp;
        return Long.compare(o.seqNum, this.seqNum); // Descending seqNum
    }
}
